SELECT srid.id, srid.main_id, srid.sku_id, srid.sku_no, srid.must_qty, srid.receive_qty, srid.real_qty, srid.return_type_dict, srid.return_reason_dict, srid.warehouse_location, srid.remark, srid.source_detail_id, sri.approve_Status FROM so_return_instock_detail srid INNER JOIN so_return_instock sri ON sri.id = srid.main_id AND srid.is_deleted = FALSE WHERE sri.is_deleted = FALSE AND sri.invalid_status = FALSE
and sri.source_id in
#{id}

